import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { ArrowRightIcon, CheckCircle, MoreVertical } from "lucide-react";
import { Link } from "raviger";
import React, { useEffect, useMemo, useState } from "react";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";

import careConfig from "@careConfig";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { EmptyState } from "@/components/ui/empty-state";
import { FilterSelect } from "@/components/ui/filter-select";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";

import Page from "@/components/Common/Page";
import { TableSkeleton } from "@/components/Common/SkeletonLoading";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/Common/Table";

import useFilters from "@/hooks/useFilters";

import CareIcon from "@/CAREUI/icons/CareIcon";
import PatientIdentifierFilter from "@/components/Patient/PatientIdentifierFilter";
import TagAssignmentSheet from "@/components/Tags/TagAssignmentSheet";
import {
  dateFilter,
  tagFilter,
} from "@/components/ui/multi-filter/filterConfigs";
import MultiFilter from "@/components/ui/multi-filter/MultiFilter";
import useMultiFilterState from "@/components/ui/multi-filter/utils/useMultiFilterState";
import {
  FilterDateRange,
  longDateRangeOptions,
} from "@/components/ui/multi-filter/utils/Utils";
import { cn } from "@/lib/utils";
import { CreateDispenseSheet } from "@/pages/Facility/services/pharmacy/CreateDispenseSheet";
import {
  ENCOUNTER_CLASS_ICONS,
  ENCOUNTER_CLASSES_COLORS,
  ENCOUNTER_STATUS_COLORS,
  ENCOUNTER_STATUS_ICONS,
} from "@/types/emr/encounter/encounter";
import {
  PrescriptionStatus,
  PrescriptionSummary,
} from "@/types/emr/prescription/prescription";
import prescriptionApi from "@/types/emr/prescription/prescriptionApi";
import { TagConfig, TagResource } from "@/types/emr/tagConfig/tagConfig";
import useTagConfigs from "@/types/emr/tagConfig/useTagConfig";
import { getLocationPath } from "@/types/location/utils";
import mutate from "@/Utils/request/mutate";
import query from "@/Utils/request/query";
import { PaginatedResponse } from "@/Utils/request/types";
import {
  dateQueryString,
  dateTimeQueryString,
  formatDateTime,
  formatName,
} from "@/Utils/utils";

export default function PrescriptionQueue({
  facilityId,
  locationId,
}: {
  facilityId: string;
  locationId: string;
}) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const { qParams, updateQuery, Pagination, resultsPerPage } = useFilters({
    limit: 14,
    cacheBlacklist: ["patient_external_id", "patient_name", "status"],
  });

  const currentTab: PrescriptionStatus =
    qParams.status || PrescriptionStatus.active;

  const tagIds = qParams.tags?.split(",") || [];
  const tagQueries = useTagConfigs({ ids: tagIds, facilityId });
  const selectedTags = tagQueries
    .map((query) => query.data)
    .filter(Boolean) as TagConfig[];

  // Create filter configurations
  const filters = useMemo(
    () => [
      tagFilter("tags", TagResource.PRESCRIPTION, "multi", "tags"),
      dateFilter("created_date", t("date"), longDateRangeOptions),
    ],
    [t],
  );

  // Handle filter updates
  const onFilterUpdate = (filterQuery: Record<string, unknown>) => {
    // Update the query parameters based on filter changes
    let query = { ...filterQuery };
    for (const [key, value] of Object.entries(filterQuery)) {
      switch (key) {
        case "tags":
          query.tags = (value as TagConfig[])?.map((tag) => tag.id).join(",");
          break;
        case "created_date":
          {
            const dateRange = value as FilterDateRange;
            query = {
              ...query,
              created_date: undefined,
              created_date_after: dateRange?.from
                ? dateQueryString(dateRange?.from as Date)
                : undefined,
              created_date_before: dateRange?.to
                ? dateQueryString(dateRange?.to as Date)
                : undefined,
            };
          }
          break;
      }
    }
    updateQuery(query);
  };

  // Use the multi-filter state hook
  const {
    selectedFilters,
    handleFilterChange,
    handleOperationChange,
    handleClearAll,
    handleClearFilter,
  } = useMultiFilterState(filters, onFilterUpdate, {
    ...qParams,
    tags: selectedTags,
    created_date:
      qParams.created_date_after || qParams.created_date_before
        ? {
            from: qParams.created_date_after
              ? new Date(qParams.created_date_after)
              : undefined,
            to: qParams.created_date_before
              ? new Date(qParams.created_date_before)
              : undefined,
          }
        : undefined,
  });

  const { data: prescriptionQueue, isLoading } = useQuery<
    PaginatedResponse<PrescriptionSummary>
  >({
    queryKey: ["prescriptionQueue", facilityId, qParams],
    queryFn: query.debounced(prescriptionApi.summary, {
      pathParams: { facilityId },
      queryParams: {
        status: currentTab,
        patient_external_id: qParams.patient_external_id,
        encounter_class: qParams.encounter_class,
        tags: qParams.tags,
        tags_behavior: qParams.tags_behavior,
        created_date_after: qParams.created_date_after
          ? dateTimeQueryString(new Date(qParams.created_date_after))
          : undefined,
        created_date_before: qParams.created_date_before
          ? dateTimeQueryString(new Date(qParams.created_date_before), true)
          : undefined,
        limit: resultsPerPage,
        offset: ((qParams.page || 1) - 1) * resultsPerPage,
      },
    }),
  });

  const isFilteredByPatient = !!qParams.patient_external_id;
  const showBillingSelection =
    isFilteredByPatient && currentTab === PrescriptionStatus.active;

  // State for selected prescription IDs
  const [selectedPrescriptionIds, setSelectedPrescriptionIds] = useState<
    string[]
  >([]);

  // Auto-select all prescriptions when billing selection is shown and data loads
  useEffect(() => {
    if (showBillingSelection && prescriptionQueue?.results) {
      setSelectedPrescriptionIds(
        prescriptionQueue.results.map((item) => item.id),
      );
    } else {
      setSelectedPrescriptionIds([]);
    }
  }, [showBillingSelection, prescriptionQueue?.results, qParams.page]);

  // Handle select all toggle
  const handleSelectAll = (checked: boolean) => {
    if (checked) {
      setSelectedPrescriptionIds(
        prescriptionQueue?.results?.map((item) => item.id) || [],
      );
    } else {
      setSelectedPrescriptionIds([]);
    }
  };

  // Handle individual checkbox toggle
  const handleSelectPrescription = (prescriptionId: string) => {
    setSelectedPrescriptionIds((prev) =>
      prev.includes(prescriptionId)
        ? prev.filter((id) => id !== prescriptionId)
        : [...prev, prescriptionId],
    );
  };

  const allSelected =
    (prescriptionQueue?.results?.length ?? 0) > 0 &&
    prescriptionQueue?.results?.every((item) =>
      selectedPrescriptionIds.includes(item.id),
    );

  const { mutate: completePrescription } = useMutation({
    mutationFn: ({
      patientId,
      prescriptionId,
    }: {
      patientId: string;
      prescriptionId: string;
    }) =>
      mutate(prescriptionApi.update, {
        pathParams: { patientId, id: prescriptionId },
      })({ status: PrescriptionStatus.completed }),
    onSuccess: () => {
      toast.success(t("prescription_marked_as_completed"));
      queryClient.invalidateQueries({
        queryKey: ["prescriptionQueue", facilityId, qParams],
      });
    },
  });

  return (
    <Page
      title={t("prescription_queue")}
      options={
        <CreateDispenseSheet
          facilityId={facilityId}
          locationId={locationId}
          patientId={qParams.patient_external_id}
        />
      }
    >
      {/* Priority tabs with original styling */}
      <div className="mb-4 pt-6">
        <Tabs
          value={currentTab}
          onValueChange={(value) => updateQuery({ status: value })}
          className="w-full"
        >
          <TabsList className="w-full justify-evenly sm:justify-start border-b rounded-none bg-transparent p-0 h-auto overflow-x-auto">
            {[
              PrescriptionStatus.active,
              PrescriptionStatus.completed,
              PrescriptionStatus.cancelled,
            ].map((key) => (
              <TabsTrigger
                key={key}
                value={key}
                className="relative px-2 sm:px-4 py-2 text-gray-600 hover:text-gray-900  data-[state=active]:text-primary-800 data-[state=active]:bg-transparent data-[state=active]:shadow-none rounded-none font-semibold transition-colors whitespace-nowrap ease-in-out"
              >
                {t(`prescription_status__${key}`)}
                <div
                  className={cn(
                    "absolute inset-x-0 bg-primary-700 h-0.75 rounded-t-md -bottom-px transition-opacity duration-200 ease-in-out",
                    currentTab === key ? "opacity-100" : "opacity-0",
                  )}
                />
              </TabsTrigger>
            ))}
          </TabsList>
        </Tabs>
      </div>
      {/* Search and filter */}
      <div className="flex flex-wrap items-center gap-2">
        <PatientIdentifierFilter
          onSelect={(patientId, patientName) =>
            updateQuery({
              patient_external_id: patientId,
              patient_name: patientName,
            })
          }
          placeholder={t("or_search_by_id")}
          className="w-full sm:w-auto rounded-md h-9 text-gray-500 shadow-sm"
          patientId={qParams.patient_external_id}
          patientName={qParams.patient_name}
        />
        <FilterSelect
          value={
            qParams.encounter_class
              ? `encounter_class__${qParams.encounter_class}`
              : ""
          }
          onValueChange={(value) =>
            updateQuery({
              encounter_class: value?.replace("encounter_class__", ""),
            })
          }
          options={careConfig.encounterClasses.map(
            (c) => `encounter_class__${c}`,
          )}
          label={t("encounter_class")}
          onClear={() => updateQuery({ encounter_class: undefined })}
        />
        <MultiFilter
          selectedFilters={selectedFilters}
          onFilterChange={handleFilterChange}
          onOperationChange={handleOperationChange}
          onClearAll={handleClearAll}
          onClearFilter={handleClearFilter}
          placeholder={t("filters")}
          className="flex flex-wrap md:flex-row items-start"
          facilityId={facilityId}
        />
      </div>

      {/* Selection bar when filtered by patient with active status */}
      {showBillingSelection && (
        <div className="mt-4 border border-gray-300 bg-white rounded-lg p-4">
          <div className="flex flex-wrap items-center gap-4">
            <div className="flex flex-col gap-1">
              <span className="text-sm font-semibold text-gray-950">
                {t("select_prescriptions_to_bill")}
              </span>
              <div className="flex items-center gap-2">
                <Checkbox
                  checked={allSelected}
                  onCheckedChange={handleSelectAll}
                  aria-label={t("select_all")}
                  id="select-all-prescriptions"
                />
                <label
                  htmlFor="select-all-prescriptions"
                  className="text-sm font-medium cursor-pointer"
                >
                  {t("select_all")}
                </label>
              </div>
            </div>
            <div className="ml-auto flex items-center gap-2">
              <Button
                variant="link"
                className={cn(
                  "underline",
                  selectedPrescriptionIds.length === 0
                    ? "pointer-events-none opacity-50"
                    : "",
                )}
                asChild
              >
                <Link
                  href={`/medication_requests/patient/${qParams.patient_external_id}/prescriptions/${selectedPrescriptionIds.join(",")}`}
                >
                  {t("preview_selected_rx")}
                </Link>
              </Button>
              <Button variant="outline_primary" asChild>
                <Link
                  href={`/medication_requests/patient/${qParams.patient_external_id}/bill/prescriptions/${selectedPrescriptionIds.join(",")}`}
                  className={
                    selectedPrescriptionIds.length === 0
                      ? "pointer-events-none opacity-50"
                      : ""
                  }
                >
                  {t("bill_selected_prescriptions")}
                  <ArrowRightIcon />
                </Link>
              </Button>
            </div>
          </div>
        </div>
      )}

      {/* Table section */}
      <div className="mt-4">
        {isLoading ? (
          <TableSkeleton count={5} />
        ) : prescriptionQueue?.results?.length === 0 ? (
          <EmptyState
            icon={
              <CareIcon
                icon="l-prescription-bottle"
                className="text-primary size-6"
              />
            }
            title={t("no_prescriptions_found")}
            description={t("no_prescriptions_found_description")}
          />
        ) : (
          <Table>
            <TableHeader>
              <TableRow>
                {showBillingSelection && <TableHead className="min-w-8" />}
                <TableHead className="w-1/3">{t("patient_name")}</TableHead>
                <TableHead className="w-1/3">
                  {t("encounter_status_location")}
                </TableHead>
                <TableHead className="w-1/3">
                  {t("tags", { count: 2 })}
                </TableHead>
                <TableHead>{t("actions")}</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {prescriptionQueue?.results?.map((item: PrescriptionSummary) => (
                <TableRow key={item.id} className="group">
                  {showBillingSelection && (
                    <TableCell>
                      <Checkbox
                        checked={selectedPrescriptionIds.includes(item.id)}
                        onCheckedChange={() =>
                          handleSelectPrescription(item.id)
                        }
                        aria-label={t("select_prescription")}
                      />
                    </TableCell>
                  )}
                  <TableCell
                    className="cursor-pointer min-h-15"
                    onClick={() => {
                      if (showBillingSelection) {
                        handleSelectPrescription(item.id);
                      } else {
                        updateQuery({
                          patient_external_id: item.encounter.patient.id,
                          patient_name: item.encounter.patient.name,
                        });
                      }
                    }}
                  >
                    <span className="underline decoration-1 underline-offset-2 font-semibold">
                      {item.encounter.patient.name}
                    </span>
                    <div className="text-sm font-medium text-gray-700 whitespace-pre-wrap">
                      <span>{formatName(item.prescribed_by)}</span>
                      <span> · </span>
                      <span>{formatDateTime(item.created_date)}</span>
                    </div>
                  </TableCell>

                  <TableCell className="text-sm">
                    <div className="flex flex-col gap-2">
                      <div className="space-x-1">
                        <Badge
                          size="sm"
                          variant={
                            ENCOUNTER_CLASSES_COLORS[
                              item.encounter.encounter_class
                            ]
                          }
                        >
                          {React.createElement(
                            ENCOUNTER_CLASS_ICONS[
                              item.encounter.encounter_class
                            ],
                            { className: "size-3" },
                          )}
                          {t(
                            `encounter_class__${item.encounter.encounter_class}`,
                          )}
                        </Badge>
                        <Badge
                          size="sm"
                          variant={
                            ENCOUNTER_STATUS_COLORS[item.encounter.status]
                          }
                        >
                          {React.createElement(
                            ENCOUNTER_STATUS_ICONS[item.encounter.status],
                            { className: "size-3" },
                          )}
                          {t(`encounter_status__${item.encounter.status}`)}
                        </Badge>
                      </div>
                      {item.encounter.current_location && (
                        <div className="bg-gray-100 py-1 px-3">
                          <span className="text-gray-800">
                            {getLocationPath(item.encounter.current_location)}
                          </span>
                        </div>
                      )}
                    </div>
                  </TableCell>

                  <TableCell>
                    <div className="flex flex-wrap gap-2">
                      <TagAssignmentSheet
                        entityType="prescription"
                        entityId={item.id}
                        facilityId={facilityId}
                        currentTags={item.tags || []}
                        onUpdate={() => {
                          queryClient.invalidateQueries({
                            queryKey: [
                              "prescriptionQueue",
                              facilityId,
                              qParams,
                            ],
                          });
                        }}
                        patientId={item.encounter.patient.id}
                      />
                    </div>
                  </TableCell>
                  <TableCell>
                    <div className="flex gap-4 items-center">
                      <span className="font-semibold underline">
                        <Button variant="link" className="underline">
                          <Link
                            href={`/medication_requests/patient/${item.encounter.patient.id}/prescriptions/${item.id}`}
                          >
                            {t("view_rx")}
                          </Link>
                        </Button>
                      </span>
                      {item.status === PrescriptionStatus.active &&
                        !isFilteredByPatient && (
                          <Button
                            variant="outline"
                            className="font-semibold text-sm text-gray-950"
                            asChild
                          >
                            <Link
                              href={`/medication_requests/patient/${item.encounter.patient.id}/bill/prescriptions/${item.id}`}
                            >
                              {t("bill_now")}
                            </Link>
                          </Button>
                        )}
                      <DropdownMenu>
                        <DropdownMenuTrigger asChild>
                          <Button variant="ghost" size="icon">
                            <MoreVertical className="h-4 w-4" />
                          </Button>
                        </DropdownMenuTrigger>
                        <DropdownMenuContent align="end">
                          <DropdownMenuItem
                            onClick={() =>
                              completePrescription({
                                patientId: item.encounter.patient.id,
                                prescriptionId: item.id,
                              })
                            }
                            disabled={item.status !== "active"}
                          >
                            <CheckCircle className="mr-2 h-4 w-4" />
                            {t("mark_prescription_complete")}
                          </DropdownMenuItem>
                        </DropdownMenuContent>
                      </DropdownMenu>
                    </div>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        )}
      </div>
      <div className="mt-8 flex justify-center">
        <Pagination totalCount={prescriptionQueue?.count || 0} />
      </div>
    </Page>
  );
}

import Loading from "@/components/Common/Loading";
import Page from "@/components/Common/Page";
import { PatientHeader } from "@/components/Patient/PatientHeader";
import { Button } from "@/components/ui/button";
import { FilterSelect } from "@/components/ui/filter-select";
import { Input } from "@/components/ui/input";
import { useShortcutSubContext } from "@/context/ShortcutContext";
import UnbilledPrescriptionsCard from "@/pages/Facility/services/pharmacy/billMedications/UnbilledPrescriptionsCard";
import PrescriptionsPreviewTable from "@/pages/Facility/services/pharmacy/components/PrescriptionsPreviewTable";
import { MedicationRequestDispenseStatus } from "@/types/emr/medicationRequest/medicationRequest";
import {
  PrescriptionRead,
  PrescriptionStatus,
} from "@/types/emr/prescription/prescription";
import prescriptionApi from "@/types/emr/prescription/prescriptionApi";
import { ShortcutBadge } from "@/Utils/keyboardShortcutComponents";
import query from "@/Utils/request/query";
import { useQueries } from "@tanstack/react-query";
import { ArrowRightIcon, ListPlus } from "lucide-react";
import { Link, useQueryParams } from "raviger";
import { useTranslation } from "react-i18next";

interface Props {
  facilityId: string;
  locationId: string;
  patientId: string;
  prescriptionIds: string[];
}

interface QParams {
  search?: string;
  status?: MedicationRequestDispenseStatus | "all";
}

export default function PrescriptionsPreviewPage({
  facilityId,
  patientId,
  prescriptionIds,
}: Props) {
  const { t } = useTranslation();
  useShortcutSubContext("facility:pharmacy");

  const [qParams, setQParams] = useQueryParams<QParams>();

  const { prescriptions, anyEncounter, activePrescriptionIds } = useQueries({
    queries: prescriptionIds.map((prescriptionId) => ({
      queryKey: ["prescription", patientId, prescriptionId],
      queryFn: query(prescriptionApi.get, {
        pathParams: { patientId, id: prescriptionId },
      }),
    })),
    combine: (results) => {
      return {
        isLoading: results.some((result) => result.isLoading),
        prescriptions: results.map((result) => result.data),
        activePrescriptionIds: results
          .filter((result) => result.data?.status === PrescriptionStatus.active)
          .map((result) => result.data?.id ?? ""),
        anyEncounter: results.find((result) => !!result.data)?.data.encounter,
      };
    },
  });

  if (!anyEncounter) {
    return <Loading />;
  }

  const statusCounts = getDispenseStatusCount(prescriptions);

  return (
    <Page title={t("prescription_preview")} hideTitleOnPage={true}>
      <div className="flex flex-col gap-3">
        <div>
          <h4 className="font-semibold text-xl">{t("prescription_preview")}</h4>
        </div>

        <div className="bg-white rounded-md border border-gray-200 p-4">
          <PatientHeader
            patient={anyEncounter.patient}
            facilityId={facilityId}
          />
        </div>

        <div className="flex justify-between">
          <div className="flex gap-3">
            <div className="w-full lg:w-64">
              <Input
                value={qParams.search || ""}
                onChange={(e) => setQParams({ search: e.target.value })}
                placeholder={t("search_medications")}
              />
            </div>
            <div className="md:flex gap-2">
              <FilterSelect
                value={qParams.status || "all"}
                onValueChange={(value) =>
                  setQParams({
                    status: value as MedicationRequestDispenseStatus | "all",
                  })
                }
                options={[
                  "all",
                  MedicationRequestDispenseStatus.incomplete,
                  MedicationRequestDispenseStatus.partial,
                  MedicationRequestDispenseStatus.complete,
                ]}
                label={t("dispense_status") as string}
                onClear={() => setQParams({ status: "all" })}
              />
            </div>
          </div>
          {activePrescriptionIds.length > 0 && (
            <Button size="lg" asChild>
              <Link
                href={`/medication_requests/patient/${patientId}/bill/prescriptions/${activePrescriptionIds.join(",")}`}
              >
                {t("start_billing")}
                <ShortcutBadge actionId="billing-action" />
                <ArrowRightIcon className="size-4" />
              </Link>
            </Button>
          )}
        </div>

        <UnbilledPrescriptionsCard
          included={prescriptionIds}
          patientId={patientId}
          facilityId={facilityId}
          allButton={({ prescriptionIds }) => (
            <Button variant="outline" size="sm" asChild>
              <Link
                href={`/medication_requests/patient/${patientId}/prescriptions/${prescriptionIds.join(",")}`}
              >
                <ListPlus className="size-4" />
                {t("show_all")}
              </Link>
            </Button>
          )}
        />

        <div className="flex justify-between">
          <div>
            <span className="font-semibold text-gray-950">
              {t("total_prescriptions_count", { count: prescriptions.length })}
            </span>
            <span className="font-normal text-gray-700">
              {" · "}
              {t("complete_count", { count: statusCounts.complete })}
              {" · "}
              {t("partial_count", {
                count: statusCounts.partial,
              })}
              {" · "}
              {t("incomplete_count", {
                count: statusCounts.incomplete,
              })}
            </span>
          </div>
        </div>

        <div className="flex flex-col gap-2">
          <PrescriptionsPreviewTable
            prescriptions={prescriptions}
            filters={{
              medicationSearch: qParams.search || "",
              medicationDispenseStatus:
                qParams.status === "all" ? null : qParams.status,
            }}
          />
        </div>
      </div>
    </Page>
  );
}

const getDispenseStatusCount = (
  prescriptions: (PrescriptionRead | undefined)[],
) => {
  let complete = 0;
  let partial = 0;
  let incomplete = 0;

  for (const prescription of prescriptions) {
    if (!prescription) {
      continue;
    }

    const medications = prescription.medications.filter(
      ({ status }) => status === "active",
    );

    if (
      medications.every(
        (medication) =>
          medication.dispense_status ===
          MedicationRequestDispenseStatus.complete,
      )
    ) {
      complete++;
      continue;
    }

    if (
      medications.every(
        (medication) =>
          (medication.dispense_status ||
            MedicationRequestDispenseStatus.incomplete) ===
          MedicationRequestDispenseStatus.incomplete,
      )
    ) {
      incomplete++;
      continue;
    }

    partial++;
  }
  return { complete, partial, incomplete };
};

import { useQueries } from "@tanstack/react-query";
import { format } from "date-fns";
import { QRCodeSVG } from "qrcode.react";
import { useTranslation } from "react-i18next";
import { formatPhoneNumberIntl } from "react-phone-number-input";

import PrintPreview from "@/CAREUI/misc/PrintPreview";
import { Markdown } from "@/components/ui/markdown";

import Loading from "@/components/Common/Loading";
import PrintTable from "@/components/Common/PrintTable";
import {
  formatAdditionalInstructions,
  formatDosage,
  formatDuration,
  formatFrequency,
  formatSig,
} from "@/components/Medicine/utils";

import query from "@/Utils/request/query";
import { formatDateTime, formatName, formatPatientAge } from "@/Utils/utils";
import { cn } from "@/lib/utils";
import useCurrentFacility from "@/pages/Facility/utils/useCurrentFacility";
import { displayMedicationName } from "@/types/emr/medicationRequest/medicationRequest";
import { getPatientIdentifiers } from "@/types/emr/patient/patient";
import { PrescriptionRead } from "@/types/emr/prescription/prescription";
import prescriptionApi from "@/types/emr/prescription/prescriptionApi";
import { PrintTemplateType } from "@/types/facility/printTemplate";
import { getLocationPath } from "@/types/location/utils";
import { PatientIdentifierUse } from "@/types/patient/patientIdentifierConfig/patientIdentifierConfig";

export interface DetailRowProps {
  label: string;
  value?: string | null;
  isStrong?: boolean;
}

const PrescriptionContent = ({
  prescription,
  prescriptionIndex,
  totalCount,
}: {
  prescription: PrescriptionRead;
  prescriptionIndex: number;
  totalCount: number;
}) => {
  const medications = prescription.medications;
  const { t } = useTranslation();

  return (
    <div>
      {/* Prescription Symbol */}
      <div className="flex justify-between items-center mb-1.5">
        <div className="flex items-center gap-2">
          <span className="font-medium text-base text-gray-950">{t("℞")}</span>
          <span className="font-semibold text-sm print:text-xs uppercase text-gray-950">
            {t("medicine_instructions")}
          </span>
          {totalCount > 1 && (
            <span className="text-sm print:text-xs text-gray-700 font-medium">
              [
              {t("x_of_y", {
                current: prescriptionIndex + 1,
                total: totalCount,
              })}
              ]
            </span>
          )}
        </div>
        <span className="text-sm print:text-xs text-gray-950">
          {formatDateTime(
            prescription.created_date,
            "DD MMM YYYY, ddd, hh:mm A",
          )}
        </span>
      </div>

      <div className="border border-gray-300 rounded-md">
        <div className="relative flex justify-between place-items-end px-4 py-3">
          <div>
            <p className="relative text-sm print:text-xs">
              <span
                aria-hidden="true"
                className="absolute top-1/2 -left-4 h-3.5 w-1 -translate-y-1/2 bg-gray-400 rounded-r-md"
              />
              <span className="text-gray-700 font-medium">
                {t("prescribed_by")}:{" "}
              </span>
              <span className="font-semibold text-gray-950">
                {formatName(prescription.prescribed_by)}
              </span>
            </p>
            {prescription.note && (
              <div className="text-xs print:text-[11px] text-gray-700 mt-0.5 flex gap-1">
                {t("note")}:
                <Markdown content={prescription.note} prose={false} />
              </div>
            )}
          </div>
        </div>
        {/* Medications Table */}
        {medications && medications.length > 0 && (
          <PrintTable
            headers={[
              { key: "hash_tag" },
              { key: "medicine" },
              { key: "dosage" },
              { key: "frequency" },
              { key: "duration" },
              { key: "instructions" },
            ]}
            rows={medications.flatMap(
              (medication, medIndex): Record<string, string | undefined>[] => {
                const instructions = medication.dosage_instruction;
                const isMulti = instructions.length > 1;
                const noteText = medication.note
                  ? `${t("note")}: ${medication.note}`
                  : undefined;
                const medicationNote =
                  isMulti && noteText ? [{ _fullspan: noteText }] : [];
                const totalRows = instructions.length + medicationNote.length;
                const shouldSpan = totalRows > 1;
                return [
                  ...instructions.map((di, idx) => ({
                    _groupedRow:
                      isMulti && idx < instructions.length - 1
                        ? "true"
                        : undefined,
                    _span_hash_tag:
                      idx === 0 && shouldSpan ? String(totalRows) : undefined,
                    _span_medicine:
                      idx === 0 && shouldSpan ? String(totalRows) : undefined,
                    hash_tag: idx === 0 ? String(medIndex + 1) : "",
                    medicine:
                      idx === 0 ? displayMedicationName(medication) : "",
                    dosage: formatDosage(di) || "",
                    frequency: formatFrequency(di) || "",
                    duration: formatDuration(di) || "",
                    instructions: [
                      formatSig(di),
                      formatAdditionalInstructions(di),
                      !isMulti ? noteText : undefined,
                    ]
                      .filter(Boolean)
                      .join("\n\n"),
                  })),
                  ...medicationNote,
                ];
              },
            )}
            cellClassName="text-sm print:text-xs wrap-break-word whitespace-break-spaces text-gray-950 font-normal text-left border-t border-gray-300"
            cellConfig={{
              hash_tag: {
                className: "text-center text-gray-600 w-8 print:w-[5%]",
              },
              medicine: {
                className: "font-medium max-w-56 min-w-32 print:w-[20%]",
              },
              dosage: { className: "w-24 print:w-[12%]" },
              frequency: { className: "min-w-24 max-w-56 print:w-[18%]" },
              duration: { className: "border-r w-20 print:w-[10%]" },
              instructions: { className: "min-w-28 max-w-56 print:w-[30%]" },
            }}
            headerClassName="text-gray-700 text-left font-normal bg-gray-50 text-xs print:text-[11px] first:rounded-none border-y border-gray-300"
            tableClassName="border-0 rounded-none"
          />
        )}
      </div>

      {/* Doctor's Signature */}

      <div className="text-right mt-20 mb-2">
        <p className="text-sm print:text-xs font-medium text-gray-950">
          {formatName(prescription.prescribed_by)}
        </p>
      </div>
    </div>
  );
};

const DetailRow = ({ label, value, isStrong = false }: DetailRowProps) => {
  return (
    <div className="grid grid-cols-[7rem_auto_minmax(0,1fr)] gap-1">
      <span className="wrap-anywhere text-gray-700 font-medium text-sm print:text-xs">
        {label}
      </span>
      <span className="text-gray-700 text-sm print:text-xs">:</span>
      <span
        className={cn(
          "ml-1 min-w-0 wrap-anywhere text-sm print:text-xs",
          isStrong ? "font-semibold text-gray-950" : "text-gray-700",
        )}
      >
        {value || "-"}
      </span>
    </div>
  );
};

interface Props {
  prescriptionIds: string[];
  patientId: string;
  facilityId: string;
}

export const PrintPrescriptions = ({
  prescriptionIds,
  patientId,
  facilityId,
}: Props) => {
  const { t } = useTranslation();
  const { facility } = useCurrentFacility();

  const { prescriptions, isLoading } = useQueries({
    queries: prescriptionIds.map((prescriptionId) => ({
      queryKey: ["prescription", patientId, prescriptionId, facilityId],
      queryFn: query(prescriptionApi.get, {
        pathParams: {
          patientId,
          id: prescriptionId,
        },
        queryParams: { facility: facilityId },
      }),
    })),
    combine: (results) => ({
      prescriptions: results
        .map((r) => r.data)
        .filter((data): data is PrescriptionRead => !!data),
      isLoading: results.some((r) => r.isLoading || r.isFetching),
    }),
  });

  const hasMedications = prescriptions.some(
    (prescription) =>
      prescription.medications && prescription.medications.length > 0,
  );

  const displayDate =
    prescriptions.length === 1 && prescriptions[0].encounter.period.start
      ? format(
          new Date(prescriptions[0].encounter.period.start),
          "dd MMM yyyy, EEEE",
        )
      : null;

  if (isLoading) {
    return <Loading />;
  }

  if (!prescriptions.length) {
    return (
      <div className="flex h-[200px] items-center justify-center rounded-lg border-2 border-dashed p-4 text-gray-500 border-gray-200">
        {t("no_prescriptions_found")}
      </div>
    );
  }

  if (!hasMedications) {
    return (
      <div className="flex h-[200px] items-center justify-center rounded-lg border-2 border-dashed p-4 text-gray-500 border-gray-200">
        {t("no_medications_found_for_this_encounter")}
      </div>
    );
  }

  const patient = prescriptions[0].encounter.patient;

  return (
    <PrintPreview
      title={`${t("prescriptions")} - ${patient.name}`}
      disabled={!hasMedications}
      facility={facility}
      templateSlug={PrintTemplateType.prescription}
      footer={
        <div className="mt-2 text-xs print:text-[10px] text-gray-900 text-center flex gap-2 justify-center">
          <span>{t("computer_generated_prescription")}</span>|
          <span>{formatDateTime(new Date(), "MMMM D, YYYY [at] h:mm A")}</span>
        </div>
      }
    >
      <div className="max-w-5xl mx-auto">
        <div>
          {/* Patient Details */}
          <div className="flex gap-4 pb-2 mb-2">
            <div className="flex min-w-0 flex-col flex-1 justify-between gap-3">
              {/* Wrap metadata columns to fit the available paper width. */}
              <div className="flex flex-wrap gap-4">
                {/* Left column: Patient, Age/Sex, Mobile */}
                <div className="min-w-0 space-y-1 flex-[3_1_14rem]">
                  <DetailRow
                    label={t("patient")}
                    value={patient.name}
                    isStrong
                  />
                  <DetailRow
                    label={`${t("age")} / ${t("sex")}`}
                    value={
                      patient
                        ? `${formatPatientAge(patient, true)}, ${t(`GENDER__${patient.gender}`)}`
                        : undefined
                    }
                    isStrong
                  />
                  <DetailRow
                    label={t("mobile_number")}
                    value={
                      patient && formatPhoneNumberIntl(patient.phone_number)
                    }
                    isStrong
                  />
                </div>

                {/* Right column: Identifiers + Encounter Date */}
                <div className="min-w-0 space-y-1 flex-[2_1_12rem] empty:hidden">
                  {getPatientIdentifiers(patient, {
                    use: PatientIdentifierUse.official,
                  }).map((identifier) => (
                    <DetailRow
                      key={identifier.config.id}
                      label={identifier.config.config.display}
                      value={identifier.value}
                      isStrong
                    />
                  ))}
                  {prescriptions.length === 1 && (
                    <DetailRow
                      label={t("encounter_date")}
                      value={displayDate}
                      isStrong
                    />
                  )}
                </div>
              </div>

              {prescriptions.length === 1 &&
                prescriptions[0].encounter.current_location && (
                  <DetailRow
                    label={t("patient_location")}
                    value={getLocationPath(
                      prescriptions[0].encounter.current_location,
                    )}
                  />
                )}
            </div>

            <div className="shrink-0">
              <QRCodeSVG
                value={patient.id}
                size={85}
                level="Q"
                marginSize={0}
              />
            </div>
          </div>

          {prescriptions.length > 1 && (
            <div className="mb-4 text-sm print:text-xs text-gray-500 border-b pb-2">
              {t("prescriptions_count", { count: prescriptions.length })}
            </div>
          )}

          {prescriptions.map((prescription, index) => (
            <div key={prescription.id}>
              {index > 0 && (
                <div className="border-t border-dashed border-gray-300 my-6" />
              )}
              <PrescriptionContent
                prescription={prescription}
                prescriptionIndex={index}
                totalCount={prescriptions.length}
              />
            </div>
          ))}
        </div>
      </div>
    </PrintPreview>
  );
};

