176	const getDispenseStatusCount = (
177	  prescriptions: (PrescriptionRead | undefined)[],
178	) => {
179	  let complete = 0;
180	  let partial = 0;
181	  let incomplete = 0;
182	
183	  for (const prescription of prescriptions) {
184	    if (!prescription) {
185	      continue;
186	    }
187	
188	    const medications = prescription.medications.filter(
189	      ({ status }) => status === "active",
190	    );
191	
192	    if (
193	      medications.every(
194	        (medication) =>
195	          medication.dispense_status ===
196	          MedicationRequestDispenseStatus.complete,
197	      )
198	    ) {
199	      complete++;
200	      continue;
201	    }
202	
203	    if (
204	      medications.every(
205	        (medication) =>
206	          (medication.dispense_status ||
207	            MedicationRequestDispenseStatus.incomplete) ===
208	          MedicationRequestDispenseStatus.incomplete,
209	      )
210	    ) {
211	      incomplete++;
212	      continue;
213	    }
214	
215	    partial++;
216	  }
217	  return { complete, partial, incomplete };
